  assert.equal(chooseViewed([{ ex: ex3, seen: 1, total: 1, dist: 1 }, { ex: ex1, seen: 4, total: 4, dist: 9 }], BALANCE).ex, ex3);
  // Away from any fence: the nearest exhibit with an animal in view, not the one with the most.
