  assert.deepEqual(zoo.events["minecraft:entity_spawned"].add.component_groups, ["zoocraft:coat_0", "zoocraft:home_8"]);
  const wild = read("../packs/BP/entities/wild_void_ray.json")["minecraft:entity"];
