  assert.match(animals, /if \(species\.canopy\) out\.push\(\.\.\.pandaWarnings\(ex, residents, fixturesOf\(ex\), pluralOf\(species\), BALANCE\.redpanda\)\);/);
  const panda = read("../packs/BP/scripts/animals/redpanda.js");
