  assert.match(nursery, /else if \(br\.carried\) tell\(ex, `§d\$\{mother\.name\}'s eggs hatched in \$\{ex\.name\}: \$\{what\}, \$\{names\}! §fThe crablets come out from under her/);
  const clip = src("../packs/BP/scripts/ui/clipboard.js");
