  assert.match(clip, /\.\.\.\(crab \? crabLines\(ex, animalsIn\(ex\)\.filter\(\(a\) => a\.speciesId === crab\.id\), crab\) : \[\]\),/);
  assert.match(clip, /minerals \? `\$\{minerals\} Mineral Feeder\$\{minerals === 1 \? "" : "s"\}` : "", aquariums \? `\$\{aquariums\} Aquarium Feeder\$\{aquariums === 1 \? "" : "s"\}` : ""\]\.filter\(Boolean\)\.join\(", "\);/);
  assert.match(clip, /Obsidian Crabs travel in a Stabilized Carrier too: 12 blocks of floor for the first, a roof over nearly all of it, rock faces to scrape/);
  const journal = src("../packs/BP/scripts/ui/fieldJournal.js");
