  assert.match(journal, /if \(sp\.rockFaces\) \{\n {6}const C = BALANCE\.crab;/);
  assert.match(src("../packs/BP/scripts/transport/carriers.js"), /"zoocraft:end_hopper", "zoocraft:shimmer_snail", "zoocraft:obsidian_crab"(, "zoocraft:chorus_moth"(, "zoocraft:starback_tortoise")?)?\]\);/, "let go, the wild one keeps its coat");
  const mc = src("../packs/BP/scripts/platform/mc.js");
