  const spawn = json("../packs/BP/spawn_rules/wild_starback_tortoise.json")["minecraft:spawn_rules"].conditions[0];
  assert.deepEqual(spawn["minecraft:biome_filter"], { test: "has_biome_tag", value: "the_end" });
