  const geo = json("../packs/RP/models/entity/starback_tortoise.geo.json")["minecraft:geometry"][0];
  const bones = new Set(geo.bones.map((b) => b.name));
  for (const b of ["tortoise", "body", "neck", "head", "legFL", "legFR", "legHL", "legHR", "tail", "tailM"]) assert.ok(bones.has(b), b);
  for (const a of Object.values(anims)) for (const b of Object.keys(a.bones ?? {})) assert.ok(bones.has(b), `animates a bone the model has: ${b}`);
