  assert.equal(JSON.stringify(pad).includes("damage"), false, "warm, not hot: it hurts nothing");
  const r = json("../packs/BP/recipes/zoocraft_warm_pad.json")["minecraft:recipe_shaped"];
  assert.deepEqual([r.tags, r.pattern, r.key.B.item, r.key.M.item, r.result], [["zoocraft_workshop"], ["BBB", " M "], "minecraft:end_bricks", "minecraft:magma", { item: "zoocraft:warm_pad", count: 1 }]);
  assert.equal(json("../packs/BP/loot_tables/blocks/zoocraft_warm_pad.json").pools[0].entries[0].name, "zoocraft:warm_pad");
  const terrain = json("../packs/RP/textures/terrain_texture.json").texture_data;
