  // The wiring: the loops, found by type, the startle only at someone in Survival or Adventure, never climbing.
  const main = src("../packs/BP/scripts/main.js");
  assert.match(main, /loop\("starbacks", 10, \d+, \(\) => tickStarbacks\(system\.currentTick\)\)/);
  assert.match(main, /loop\("starbackmove", 1, \d+, tickStarbackMoves\)/);
  assert.match(main, /initStarbacks\(\);/);
