test("Block readers: gates and doors have their states read, liquids are told by type", async () => {
  const { readsOpen, LIQUID_TYPES } = await import("../packs/BP/scripts/data/blocks.js");
  for (const id of ["minecraft:oak_fence_gate", "minecraft:spruce_door", "minecraft:iron_door", "zoocraft:keeper_gate", "zoocraft:keeper_gate_top", "minecraft:oak_fence"]) assert.equal(readsOpen(id), true, id);
  for (const id of ["minecraft:stone", "minecraft:glass", "minecraft:iron_trapdoor", "minecraft:water", "minecraft:cobblestone_wall"]) assert.equal(readsOpen(id), false, id);
  // Every block whose category, read any way, depends on open or shut is one readsOpen picks out.
  const ids = ["minecraft:oak_fence_gate", "minecraft:crimson_fence_gate", "minecraft:birch_door", "minecraft:wooden_door", "minecraft:iron_door", "minecraft:copper_door", "minecraft:oak_trapdoor", "minecraft:iron_trapdoor", "minecraft:oak_fence", "minecraft:nether_brick_fence", "minecraft:iron_bars", "minecraft:glass_pane", "minecraft:cobblestone_wall", "minecraft:stone", "minecraft:oak_log", "minecraft:oak_leaves", "zoocraft:keeper_gate", "zoocraft:keeper_gate_top", "zoocraft:end_fence", "minecraft:bamboo_fence_gate", "minecraft:cherry_door"];
  const ways = [{}, { boar: true }, { climb: true, leaves: true }, { ape: true, climb: true }, { gecko: true, thin: true }, { croc: true }, { perch: true }];
  for (const id of ids) for (const w of ways) {
    const shut = classifyBlock(id, { isAir: false, isLiquid: false, open: false, ...w });
    const open = classifyBlock(id, { isAir: false, isLiquid: false, open: true, ...w });
    if (shut !== open) assert.equal(readsOpen(id), true, `${id} ${JSON.stringify(w)}`);
  }
  assert.deepEqual([...LIQUID_TYPES].sort(), ["minecraft:flowing_lava", "minecraft:flowing_water", "minecraft:lava", "minecraft:water"]);
  assert.equal(classifyBlock("minecraft:water", { isAir: false, isLiquid: true, open: false }), "water");
  assert.equal(classifyBlock("minecraft:lava", { isAir: false, isLiquid: true, open: false }), "lava");
  const mc = readFileSync(new URL("../packs/BP/scripts/platform/mc.js", import.meta.url), "utf8");
  assert.match(mc, /opts\.isLiquid = LIQUID_TYPES\.has\(f\.typeId\);/);
  assert.match(mc, /if \(opens\) \{\n\s+const states = block\.permutation\.getAllStates\(\);/, "only a gate or door has its states read");
});

