  assert.ok(sim({ sculk: false }) <= T.sculkComfortCap && sim({ shriek: false }) <= T.shriekComfortCap && sim({}) > T.sculkComfortCap, "the caps hold comfort down");
  for (const s of ["const sculk = hasSculkFloor(species, ex);", "const shriek = isQuiet(species, ex);", "lush, clay, burrow, sculk, shriek }, BALANCE);", "lush, clay, burrow, sculk, shriek };", "if (species.sculkFloor) out.push(...skulkerWarnings(ex, residents, pluralOf(species), species, BALANCE));"]) assert.ok(src("animals/animals.js").includes(s), s);
  // The warnings: the dark (from the house measure), the sculk, the shrieker.
  assert.deepEqual(K.skulkerWarnings({ house: dark, skulker: { sculk: 12, shriekers: 0 } }, [], "Skulkers", sk, BALANCE), []);
  const ws = K.skulkerWarnings({ house: sunny, skulker: { sculk: 3, shriekers: 1 } }, [], "Skulkers", sk, BALANCE);
  assert.equal(ws.length, 3);
  assert.match(ws[0].text, /^Skulkers live in the dark: no daylight on the floor .*Now: daylight reaches 144 of 144 blocks.*Comfort can't rise above 50 until it's dark\./);
  assert.match(ws[1].text, /^Skulkers need 8 or more blocks of sculk in the floor .*\(3 now; comfort can't rise above 50 without it\)\.$/);
  assert.match(ws[2].text, /^A sculk shrieker in or beside the floor frightens skulkers \(1 now; comfort can't rise above 30\): take it out\. Sculk sensors are fine\.$/);
  // The clipboard.
  const lines = K.skulkerLines({ house: dark, skulker: { sculk: 12, shriekers: 0 } }, [{ id: "a" }, { id: "b", juvenile: true }], sk, BALANCE);
  assert.deepEqual([lines[0], lines[2], lines[3]], ["§fDark: §ayes§7 (dimly lit; they glow, so guests see them)", "§fSculk shriekers: §anone§7 (sculk sensors are fine)", "§fSculklings: §71: they follow their mother about"]);
  assert.match(lines[1], /^§fSculk: §a12§7 of 8 \(/);
  assert.match(K.skulkerLines({ house: sunny }, [], sk, BALANCE)[0], /^§fDark: §cno§7: daylight reaches 144 of 144 blocks/);
  assert.match(K.skulkerLines({}, [], sk, BALANCE)[1], /not measured yet/);
  assert.match(src("ui/clipboard.js"), /\.\.\.\(skulker \? skulkerLines\(ex, animalsIn\(ex\)\.filter\(\(a\) => a\.speciesId === skulker\.id\), skulker, BALANCE\) : \[\]\),/);
  // Hearing: someone who moved more than T.moveMin since the last look (half a second before), not sneaking or a
  // spectator; the nearest in its dimension within T.hearRange.
  assert.deepEqual([K.madeSound({ x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }, false, false, T.moveMin), K.madeSound({ x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }, true, false, T.moveMin), K.madeSound({ x: 0, y: 0, z: 0 }, { x: 0.2, y: 0, z: 0 }, false, false, T.moveMin), K.madeSound(undefined, { x: 1, y: 0, z: 0 }, false, false, T.moveMin), K.madeSound({ x: 0, y: 0, z: 0 }, { x: 0, y: 1, z: 0 }, false, true, T.moveMin)], [true, false, false, false, false]);
  const ow = "minecraft:overworld";
  const heard = [{ id: "far", location: { x: 9, y: 0, z: 0 }, dimension: ow }, { id: "near", location: { x: 0, y: 0, z: 5 }, dimension: ow }, { id: "nether", location: { x: 1, y: 0, z: 0 }, dimension: "minecraft:nether" }];
  assert.deepEqual([K.hearing({ x: 0, y: 0, z: 0 }, ow, heard, T.hearRange)?.id, K.hearing({ x: 0, y: 0, z: 0 }, ow, heard.slice(0, 1), T.hearRange), K.hearing({ x: 0, y: 0, z: 0 }, "minecraft:nether", heard, T.hearRange)?.id], ["near", undefined, "nether"]);
  // The day: up by day, resting at night: dug into sculk (or a sculk vein), sitting elsewhere.
